import json
data = json.load(open('/app/resources/treasury_bulletin_1988_03.json'))
for elem in data['document']['elements'][:5]:
    print('Element:', elem.get('id'), 'Type:', elem.get('type'))
    if 'content' in elem:
        content = elem['content']
        if isinstance(content, dict):
            print('Content keys:', list(content.keys())[:10])
        elif isinstance(content, str):
            print('Content:', content[:300])
    print('---')
